using System; using Microsoft.UI.Xaml; using Windows.Services.Store; using WinRT.Interop; using System.IO; using Newtonsoft.Json.Linq; using System.Threading.Tasks;  namespace Playgama.Bridge.Wrappers.MicrosoftStore {     public sealed partial class MainWindow : Window     {         private readonly StoreContext _store;         private readonly nint _hwnd;          private const string AppSettingsFileName = "appsettings.json";          private sealed class AppConfiguration         {             public required string ClientId { get; init; }             public required Uri ServiceTicketBaseUrl { get; init; }              public Uri ServiceTicketEndpoint => new(ServiceTicketBaseUrl, "/api/bridge/v1/microsoft-store/service-ticket");         }          private static AppConfiguration? _config;          private static async Task<AppConfiguration> LoadConfigurationAsync()         {             var path = Path.Combine(AppContext.BaseDirectory, AppSettingsFileName);              var text = File.Exists(path)                 ? await File.ReadAllTextAsync(path).ConfigureAwait(false)                 : "";              var json = string.IsNullOrWhiteSpace(text) ? new JObject() : JObject.Parse(text);              var clientId = (string?)json["clientId"] ?? "";             var baseUrl = (string?)json["serviceTicketBaseUrl"] ?? "";              return new AppConfiguration             {                 ClientId = clientId,                 ServiceTicketBaseUrl = Uri.TryCreate(baseUrl, UriKind.Absolute, out var uri) ? uri : new Uri("https://playgama.com"),             };         }          private static async Task EnsureConfigurationLoadedAsync()         {             _config ??= await LoadConfigurationAsync().ConfigureAwait(false);         }          private static AppConfiguration GetConfiguration()         {             if (_config is null)                 throw new InvalidOperationException("Configuration not loaded. Call EnsureConfigurationLoadedAsync() at startup.");             return _config;         }          public MainWindow()         {             InitializeComponent();              _hwnd = WindowNative.GetWindowHandle(this);              SetWindowIcon("Assets\\favicon.ico");              ExtendsContentIntoTitleBar = true;             SetTitleBar(AppTitleBar);              _store = StoreContext.GetDefault();             InitializeWithWindow.Initialize(_store, _hwnd);              _ = EnsureConfigurationLoadedAsync();              _ = InitializeAsync();         }     } } 